export type Wl002Lesson = { title: string; explanation: string; practice: string; application: string }
export type Wl002Chapter = { title: string; introduction: string; objectives: string[]; legalContext: string; lessons: Wl002Lesson[]; exercises: string[]; summary: string[] }

// Written course manuscript. A lesson separates explanation, observation and
// application; the renderer and interactions remain the existing LessonPlayer.
export const wl002Curriculum: Wl002Chapter[] = [
  {
    title: 'De preventiemedewerker: rol, taken en positie',
    introduction: 'Een benoeming maakt de preventie nog niet werkzaam. U moet weten wat uw bijdrage is, welke informatie u nodig heeft en wie besluiten kan nemen. In dit hoofdstuk bouwt u een werkbare positie op: dichtbij het dagelijkse werk, met een duidelijke lijn naar werkgever, medewerkers, medezeggenschap en deskundigen. U hoeft WL-001 niet te hebben gevolgd; de noodzakelijke RI&E-basis komt in het volgende hoofdstuk aan bod.',
    objectives: ['De drie wettelijke kerntaken onderscheiden van aanvullende organisatieafspraken.', 'Uitleggen waarom de werkgever verantwoordelijk blijft voor het arbobeleid.', 'Een werkbare rolafspraak maken over tijd, middelen, overleg en escalatie.', 'De grens tussen opleidingsafronding en formele deskundigenkwalificatie herkennen.'],
    legalContext: 'Wettelijke context: artikel 13 Arbowet regelt deskundige bijstand door werknemers. De kerntaken betreffen meewerken aan RI&E, adviseren en samenwerken met OR/PVT en deskundigen, en medewerking aan maatregelen. De werkgever blijft verantwoordelijk. Bij ten hoogste 25 werknemers kan de werkgever onder voorwaarden zelf deze taken verrichten. Persoon en positie raken het instemmingsrecht van OR/PVT. Praktische aanbeveling: leg taken, tijd en overleg schriftelijk vast; een bepaald standaardfunctieprofiel is daarmee niet als algemene wettelijke vorm voorgeschreven.',
    lessons: [
      { title: 'Ondersteunen is niet overnemen', explanation: 'De preventiemedewerker brengt werkkennis en risicoinformatie bij elkaar. U helpt onderzoeken, adviseert en volgt acties. De werkgever organiseert beleid, middelen en uitvoering en blijft daarvoor verantwoordelijk. Dit onderscheid is ook praktisch: wie geen budget of lijnbevoegdheid heeft, kan niet zonder afspraken alle oplossingen afdwingen. Andersom ontslaat dat u niet van zorgvuldig signaleren en tijdig adviseren.\nEen passende rol is actief zonder alles naar zich toe te trekken. Benoem wat u zelf doet, wie beslist en bij wie een blokkade wordt besproken. Zo blijft een advies niet hangen in een mailbox en krijgt een medewerker geen onrealistische verantwoordelijkheid.', practice: 'Een logistiek bedrijf schrijft op de functiekaart: “De preventiemedewerker zorgt dat de hele organisatie veilig is.” Er zijn twee uur per maand beschikbaar en geen overlegafspraken. Bij een kapotte afscherming verwijst de teamleider naar deze functiekaart.', application: 'Herschrijf de afspraak naar concrete ondersteuning: u registreert het signaal, bespreekt het risico met de verantwoordelijke en volgt het besluit. De werkgever belegt herstel, tijdelijke bescherming en middelen. Spreek af wat gebeurt als herstel niet op tijd lukt.' },
      { title: 'Drie kerntaken in dagelijks werk', explanation: 'Meewerken aan de RI&E betekent bijvoorbeeld informatie ophalen, werkplekken kennen en ontbrekende onderwerpen signaleren. Adviseren en samenwerken betekent bevindingen bespreken, deskundigheid inschakelen en medewerkersvertegenwoordiging betrekken. Meewerken aan maatregelen betekent helpen organiseren, instrueren en controleren wat de uitvoering oplevert.\nAanvullende taken kunnen nuttig zijn, zoals een rondgang plannen of een actielijst beheren. Maak duidelijk dat dit organisatieafspraken zijn. Taken zoals medische diagnostiek of formele specialistische toetsing volgen niet automatisch uit de benoeming.', practice: 'In een zorgorganisatie vraagt men de preventiemedewerker zowel een werkplekrondgang te plannen als medische klachten van individuele medewerkers te beoordelen. In de agenda heten beide activiteiten “preventie”.', application: 'Koppel de rondgang aan RI&E en maatregelen. Beperk gesprekken over klachten tot relevante werksignalen en verwijs medische beoordeling naar de passende professional. Een handige taaknaam verandert de deskundigheidsgrens niet.' },
      { title: 'Kleine werkgever: mogelijkheid met voorwaarden', explanation: 'De omvang van een organisatie kan bepalen of de werkgever zelf de preventietaken mag uitvoeren. Dat is geen vrijstelling van de taken of de noodzaak van voldoende kennis en middelen. Beoordeel wat de werkzaamheden werkelijk vragen. Een technisch complex bedrijf kan ondersteuning nodig hebben, ook wanneer weinig mensen in dienst zijn.\nEen cursus helpt kennis opbouwen, maar vervangt die afweging niet. Breng ervaring, tijd, risico’s en beschikbare expertise in samenhang in beeld. De juridische toepassing van aantallen en organisatiegrenzen vraagt zo nodig nader advies; improviseer geen eigen uitzonderingsregel.', practice: 'De eigenaar van een metaalbedrijf met achttien medewerkers wil zelf preventiemedewerker zijn. Hij kent de productie goed, maar zegt weinig tijd te hebben voor opvolging en onvoldoende te weten van blootstelling bij lassen.', application: 'Bespreek beschikbare tijd en welke kennis aanvullend nodig is. Organiseer passende ondersteuning voor de lasvraag en maak opvolging onderdeel van de werkafspraken. Het kleine personeelsaantal is geen bewijs dat ieder risico eenvoudig is.' },
      { title: 'Tijd, middelen en toegang regelen', explanation: 'Een preventierol vraagt toegang tot informatie en mensen. Denk aan actuele RI&E, PvA, relevante instructies, onderhoudsafspraken en overleg met medewerkers. Vraag geen medische dossiers om een volledig beeld te krijgen; richt u op werk en risico’s.\nMaak een haalbare eerste planning. Reserveer naast rondgangen ook tijd voor gesprekken, voorbereiding en opvolging. Als de tijd structureel niet past, maak de gevolgen zichtbaar: welke controles blijven liggen, welke besluiten ontbreken en welke risico’s vragen nu aandacht? Een stille overbelasting van de preventiemedewerker is geen duurzame oplossing.', practice: 'Een school benoemt een docent naast een volle lesweek. Rondes worden drie maanden uitgesteld. De docent wil ze voortaan in privéweekenden uitvoeren om collega’s niet te belasten.', application: 'Bespreek de preventietaak met de werkgever als werk dat georganiseerd moet worden. Onderbouw benodigde tijd met concrete activiteiten en prioriteiten. Leg vast wie bij afwezigheid dringende signalen oppakt.' },
      { title: 'Positie en onafhankelijk adviseren', explanation: 'Onafhankelijk adviseren vraagt ruimte om ook een ongunstige bevinding te benoemen. Gebruik controleerbare feiten en een passende overleglijn. Een stevige positie betekent niet dat u iedere discussie wint of zonder onderbouwing besluiten neemt. U moet uw advies kunnen toelichten en onzekerheid zichtbaar houden.\nMaak afspraken over rapportage en escalatie en betrek de medezeggenschap waar dat hoort. Presenteer bescherming van de positie niet als een onvoorwaardelijke garantie voor iedere situatie. De concrete juridische toepassing vraagt review. In de dagelijkse praktijk helpen een duidelijk mandaat en zorgvuldige verslaglegging om de rol professioneel uit te oefenen.', practice: 'In een productieoverleg wil men een terugkerende storing niet in het preventieverslag opnemen omdat dit de leverbetrouwbaarheid ongunstig laat lijken. De waarnemingen zijn feitelijk bevestigd.', application: 'Handhaaf de relevante feiten, vermeld de context en bespreek waarom opvolging nodig is. Gebruik de afgesproken lijn wanneer geen besluit volgt. Verspreid het verslag niet ongericht als manier om druk uit te oefenen.' },
      { title: 'Uw eerste werkbare rolafspraak', explanation: 'Begin niet met een allesomvattend plan voor het hele bedrijf. Maak een eerste kaart van de belangrijkste risico’s, mensen, informatie en lopende acties. Vraag wat al werkt en wat vastloopt. Zo voorkomt u dubbel onderzoek en merkt u snel waar uw bijdrage het meest nodig is.\nEen bruikbare rolafspraak noemt kerntaken, beschikbare uren en middelen, overlegpartners, rapportage en een route voor urgente situaties. Bespreek hoe de afspraak wordt geëvalueerd. De vorm is een praktisch hulpmiddel; het gaat om de werking. Een digitaal functieprofiel zonder tijd of opvolging maakt preventie niet vanzelf beter.', practice: 'Een nieuwe preventiemedewerker in een kantoororganisatie ontvangt vijf losse spreadsheets. Niemand weet welke actielijst actueel is. Zij wil eerst één overleg met werkgever en medewerkersvertegenwoordiging om het vertrekpunt te bepalen.', application: 'Breng de actuele RI&E en PvA-versie, actie-eigenaren en bestaande overlegafspraken samen. Maak daarna een beperkte eerste periodeplanning. Controleer na enkele weken of meldingen en besluiten de juiste mensen bereiken.' },
    ],
    exercises: ['Een directeur benoemt u en wil de volledige arboveiligheid aan u overdragen. Wie blijft verantwoordelijk voor het arbobeleid?', 'Uw werkplan bevat medische verzuimdiagnoses naast RI&E-ondersteuning. Welke werkzaamheden zijn wettelijke preventiekerntaken?', 'Een ondernemer met twintig werknemers wil de taken zelf doen. Welke toets is naast het aantal werknemers nodig?', 'Uw rondes worden door roosterdruk telkens geschrapt. Wat moet u als eerste bespreekbaar maken?', 'Het team verwart een rolbeschrijving met een juridische vrijwaring. Waarvoor is de rolbeschrijving bedoeld?', 'Een teamleider wil alleen positieve bevindingen laten rapporteren. Welke afspraak helpt onafhankelijk adviseren?', 'Een collega wil na deze opleiding automatisch formele RI&E-toetsing aanbieden. Welke begrenzing is juist?', 'U start in een onbekende zorgorganisatie. Welke twee activiteiten helpen u een bruikbaar vertrekpunt te krijgen?', 'De werkgever koopt extern advies in en vraagt wat intern nog georganiseerd moet zijn. Welke vervolgvraag past?'],
    summary: ['Ondersteunen en adviseren draagt werkgeversverantwoordelijkheid niet over.', 'Koppel de drie kerntaken aan concrete activiteiten en passende deskundigheid.', 'Regel tijd, informatie, overleg en escalatie en evalueer of die werken.', 'Een opleidingscertificaat is geen wettelijke beroepskwalificatie of formele toetsbevoegdheid.'],
  },
  {
    title: 'RI&E en Plan van Aanpak in de praktijk',
    introduction: 'De RI&E vormt het overzicht van risico’s in het werk; het Plan van Aanpak verbindt dat overzicht aan verbetering. U leert zonder vooropleiding hoe gevaar, blootstelling, beoordeling, maatregel en opvolging samenhangen. De preventiemedewerker helpt deze samenhang bewaken, ook wanneer de RI&E door een externe partij is opgesteld.',
    objectives: ['Gevaar, blootstelling en risico onderscheiden.', 'Ontbrekende informatie herkennen voordat u een risico beoordeelt.', 'Een risico vertalen naar een concrete PvA-actie met eigenaar en controle.', 'Actualisatie en voorwaarden rond deskundige toetsing zorgvuldig bespreken.'],
    legalContext: 'Wettelijke context: artikel 5 Arbowet betreft RI&E en Plan van Aanpak; maatregelen moeten op arbeidsrisico’s aansluiten. Toetsing kent een hoofdregel en voorwaardelijke uitzonderingen. Het gebruiken van een branche-instrument geeft niet zonder meer een algemene vrijstelling. Een RI&E heeft geen algemene vaste vervaldatum van vijf jaar. Praktische aanbeveling: organiseer een regelmatig voortgangsoverleg naast actualisatie wanneer werk, kennis of omstandigheden veranderen.',
    lessons: [
      { title: 'Van gevaar naar blootstelling', explanation: 'Een gevaar is bijvoorbeeld bewegend verkeer, een schadelijke stof of een zware handeling. Om het risico te begrijpen moet u weten wie eraan wordt blootgesteld, hoe vaak, hoe lang en onder welke omstandigheden. Een inventarisatie die alleen “heftruck aanwezig” vermeldt, vertelt nog weinig over voetgangers tijdens piekdrukte.\nKijk ook naar niet-routinematig werk: schoonmaken, storingen, onderhoud en levering. Vraag welke groepen u nog mist, zoals tijdelijke medewerkers of mensen buiten de dagdienst. Beschrijf feitelijk wat bekend is. Daarmee legt u de basis voor een beoordeling die op de eigen situatie berust.', practice: 'Een laboratorium vermeldt “reinigingsmiddel” in de RI&E. Het middel wordt normaal gesloten gebruikt, maar tijdens wekelijkse reiniging handmatig overgegoten. De schoonmaakploeg werkt buiten de gebruikelijke kantooruren.', application: 'Neem de reiniging en betrokken groep expliciet mee. Verzamel stofinformatie, duur, handelingen en bestaande bescherming. Beoordeel niet alleen de opslag of het normale productiegebruik.' },
      { title: 'Beoordelen met zichtbare onzekerheid', explanation: 'Prioriteit volgt uit onderbouwde risico-informatie, niet uit de stelligheid van de melder of de prijs van een oplossing. Mogelijke ernst en blootstelling zijn belangrijk. Gebruik een passende methode en begrijp de beperkingen; een cijfer maakt een onvolledige inventarisatie niet betrouwbaar.\nOntbrekende informatie vraagt een expliciet vervolg. Soms is gericht verdiepend onderzoek nodig, bijvoorbeeld bij blootstelling of complexe beveiliging. Leg de vraag vast en bespreek welke bescherming intussen nodig is. De uitkomsten voeden vervolgens de RI&E en maatregelen. Verwijder het onderwerp niet omdat onderzoek nog loopt.', practice: 'In een zorgteam is zwaar tillen zichtbaar. Het is onduidelijk hoe vaak hulpmiddelen ontbreken in avonddiensten. De teamleider wil toch alvast “laag” noteren omdat overdag meestal met twee mensen wordt gewerkt.', application: 'Maak het gebrek aan avondinformatie zichtbaar. Onderzoek representatieve handelingen en beschikbare hulp. Bespreek tussentijdse bescherming en laat een gunstige dagobservatie niet automatisch voor alle diensten gelden.' },
      { title: 'Maatregelen in een bewuste volgorde', explanation: 'Onderzoek eerst of het gevaar bij de bron kan worden weggenomen of verminderd. Vervolgens komen passende technische of collectieve oplossingen en organisatorische maatregelen in beeld; persoonlijke bescherming kan aanvullend nodig zijn. De precieze afweging moet passen bij het risico en het geldende kader.\nEen training kan waardevol zijn, maar verandert een ongeschikte werkplek niet vanzelf. Vraag welke foutmogelijkheden in het proces kunnen worden voorkomen en welke bescherming onafhankelijk van voortdurend correct gedrag werkt. Leg keuzes en beperkingen vast. Zo wordt de maatregelenhiërarchie een redenering in plaats van een plaatje in het beleid.', practice: 'Een technische dienst gebruikt een oplosmiddel bij dagelijks reinigen. Medewerkers vragen om betere handschoenen. Een minder schadelijk product en een gesloten reinigingsmethode zijn nog niet onderzocht.', application: 'Onderzoek geschiktheid van bron- en technische alternatieven. Beoordeel tegelijk de bestaande bescherming en benodigde tijdelijke maatregelen. Een lager geplaatste maatregel kan nodig zijn, maar mag het onderzoek naar een betere aanpak niet onzichtbaar vervangen.' },
      { title: 'Het Plan van Aanpak uitvoerbaar maken', explanation: 'Een actie moet duidelijk maken welk risico zij vermindert, wat wordt gedaan, wie uitvoering organiseert en wanneer dat gebeurt. Voeg toe hoe u controleert of de maatregel werkt en wie het beheer overneemt. Een algemene formulering zoals “aandacht voor ergonomie” is niet voldoende voor dagelijkse sturing.\nDe preventiemedewerker kan helpen aanscherpen en voortgang volgen. Maak niet alle acties automatisch van uzelf. Een verantwoordelijke heeft passende taak, middelen en beslissingsruimte nodig. Als een besluit ontbreekt, hoort dat zichtbaar in de overleglijn. Het PvA is geen verlanglijst zonder eigenaarschap.', practice: 'Een kantoorteam noteert “bureaus verbeteren”. Er is geen eigenaar, termijn of beeld van de klachten over de werkopstelling. De manager denkt dat een offerte aanvragen hetzelfde is als afronden.', application: 'Maak de actie concreet: onderzoek representatieve werkplekken, bepaal passende aanpassing en instructie, beleg uitvoering en controleer gebruik. Noteer de termijn en wie over middelen beslist.' },
      { title: 'Toetsing en externe ondersteuning', explanation: 'Een passende RI&E en eventuele toetsing zijn verschillende vragen. De preventiemedewerker kan informatie helpen verzamelen en de uitvoering ondersteunen; dat maakt hem niet automatisch formeel toetser. Wanneer toetsing nodig is en welke uitzondering toepasbaar is, hangt af van voorwaarden in de eigen situatie.\nControleer bijvoorbeeld of het gebruikte instrument past en of aan de voorwaarden voor een uitzondering is voldaan. Presenteer “kleiner dan 25” niet als zelfstandige algemene vrijstelling. Leg vast wie de toepasselijkheid nagaat en vraag deskundig advies bij twijfel. Een externe offerte met het woord “check” zegt op zichzelf niets over de wettelijke scope.', practice: 'Een onderwijsorganisatie heeft een branche-instrument ingevuld. Een collega wil daarom het onderwerp toetsing afsluiten. In het dossier is niet vastgelegd of het instrument voor deze organisatie en versie passend is.', application: 'Laat de voorwaarden en gebruikte bron controleren. Bewaar de onderbouwing bij de RI&E. De uitkomst kan een uitzondering of een noodzakelijke toetsing zijn; neem die conclusie niet vooraf aan.' },
      { title: 'Actueel houden en voortgang bewaken', explanation: 'Nieuwe werkzaamheden, verbouwing, andere middelen of nieuwe inzichten kunnen de risico’s veranderen. Wacht dan niet uitsluitend op een vaste evaluatiedatum. Een periodiek overleg is nuttig om ook zonder grote verandering naar open acties en werking te kijken. Het is een organisatorisch ritme, geen algemene wettelijke vijfjaarstermijn.\nKoppel vertraging aan risico en bescherming. Een nieuwe besteldatum is geen maatregel. Bespreek de oorzaak, tijdelijke beheersing en een verantwoord vervolg. Actualiseer RI&E en PvA waar de informatie daarom vraagt en behoud een herleidbaar beeld van besluiten. De cyclus blijft verbonden met het werk.', practice: 'Een verbouwing wordt vervroegd terwijl de RI&E uit het vorige jaar komt. Routes en opslag veranderen, maar de jaarplanning bevat pas over acht maanden een evaluatie.', application: 'Onderzoek de verandering nu, bespreek tijdelijke en definitieve routes en leg uitvoering en controle vast. Pas de planning en relevante documentatie aan in plaats van het jaartal als veiligheidsbewijs te gebruiken.' },
    ],
    exercises: ['Een nieuwe verpakkingslijn ontbreekt in de inventarisatie. Wat is de eerste stap?', 'Een PvA vermeldt “geluid aanpakken” zonder uitvoeringsafspraken. Welke gegevens ontbreken?', 'Een zorgteam heeft geen gegevens over avondbelasting. Wat doet u vóór een definitieve risicoconclusie?', 'Een collega noemt een losse boodschappenlijst de volledige RI&E. Wat onderscheidt de inventarisatie?', 'Een RI&E van drie jaar oud mist een nieuw proces. Welke actualiteitsvraag gaat vóór de documentleeftijd?', 'Een structurele aanpassing is vertraagd. Wat bespreekt u over het nog aanwezige risico?', 'Een werkplaats kan een schadelijke stof mogelijk vervangen. Welke keuze staat hoger in de maatregelenhiërarchie?', 'Bij prioritering is alleen de offerteprijs bekend. Welke risico-informatie hoort mee te wegen?', 'Een branche-instrument is gebruikt zonder dossier over toepasselijkheid. Welke vervolgvraag past?'],
    summary: ['Beschrijf gevaar, blootstelling en context vóór beoordeling.', 'Maak onzekerheid opvolgbaar en organiseer deskundigheid waar nodig.', 'Koppel maatregelen aan risico, eigenaar, termijn, effect en beheer.', 'Actualiseer op inhoud en controleer toetsingsvoorwaarden zonder algemene vrijstellingsclaims.'],
  },
  {
    title: 'Werkplekrondes uitvoeren',
    introduction: 'Een werkplekrondgang helpt zien hoe het werk werkelijk wordt uitgevoerd. Het is geen zoektocht naar schuld en ook geen vervanging voor ieder specialistisch onderzoek. U oefent een gerichte voorbereiding, feitelijke observatie, open gesprek en bruikbare terugkoppeling. De opbrengst moet aansluiten op RI&E, beoordeling en opvolging.',
    objectives: ['Een rondgang voorbereiden met relevante risico’s en representatieve werkmomenten.', 'Waarneming, interpretatie en ontbrekende informatie onderscheiden.', 'Open vragen stellen zonder medewerkers als probleem te behandelen.', 'Bevindingen omzetten in beoordeelbare en opvolgbare acties.'],
    legalContext: 'Wettelijke context: de rondgang kan bijdragen aan RI&E en deskundige ondersteuning, maar is niet automatisch een formele RI&E-toetsing. Bescherming en passende instructie blijven werkgeversverantwoordelijkheden. Praktische aanbeveling: combineer observaties met gesprekken, bestaande risico-informatie en representatieve momenten. Handel bij mogelijk direct gevaar volgens de geldende veiligheids- en escalatieafspraken; deze opleiding geeft geen nieuwe technische of juridische bevoegdheden.',
    lessons: [
      { title: 'Kies een vraag en een representatief moment', explanation: 'Begin met wat u wilt begrijpen: verkeersstromen, fysieke belasting, onderhoud of een andere relevante taak. Lees bestaande RI&E-punten, meldingen en open acties. Kies een route en tijdstip waarop die werkzaamheden echt zichtbaar zijn. Een nette werkplek vlak voor een bezoek kan een ander beeld geven dan de avondpiek.\nNeem de context mee in de verslaglegging. Als u een bijzonder of rustig moment ziet, is dat nog steeds informatie, maar geen bewijs voor alle situaties. Plan zo nodig een tweede moment of betrek mensen uit andere diensten. Het doel is voldoende variatie zien, niet zoveel mogelijk vakjes afvinken.', practice: 'Een logistieke ronde is gepland om elf uur, tussen twee laadpieken. De vorige incidenten vonden plaats bij gelijktijdig laden en terugbrengen van lege karren.', application: 'Verplaats of vul de ronde aan met een piekmoment. Vraag vooraf naar afwijkende routes, bezoekers en tijdelijke medewerkers. Beschrijf wat deze waarneming wel en niet over het totale verkeer kan zeggen.' },
      { title: 'Feitelijk waarnemen en vastleggen', explanation: 'Noteer wat u ziet: plaats, tijd, taak, betrokken groepen en aanwezige bescherming. “Doorgang geblokkeerd door twee rolcontainers tijdens levering” is bruikbaarder dan “team werkt slordig”. Houd interpretaties herkenbaar apart en formuleer welke informatie ontbreekt.\nEen foto kan helpen als het veilig en toegestaan is, maar is geen volledige analyse. Vermijd onnodige personen of persoonsgegevens in beeld. Koppel de foto aan context en een vervolgvraag. Een waarneming wordt pas een bruikbare bevinding wanneer iemand kan begrijpen onder welke omstandigheden zij relevant is.', practice: 'In een schoolgang staan dozen tijdens het uitpakken. De route wordt later ook door kinderen en bezoekers gebruikt. Een medewerker zegt dat de dozen na tien minuten weg zijn.', application: 'Noteer duur, routegebruik en alternatieven en vraag naar de leverroutine. Beoordeel of tijdelijke blokkering een risico geeft in de feitelijke situatie; een korte duur maakt de bevinding niet vanzelf onbelangrijk.' },
      { title: 'Vraag naar het verschil tussen papier en werk', explanation: 'Medewerkers kennen variaties die een document niet toont. Vraag hoe het gaat bij drukte, storing, een ontbrekend hulpmiddel of een nieuwe collega. Vermijd vragen die alleen bevestiging van naleving uitnodigen. Een open gesprek kan duidelijk maken waarom een ogenschijnlijk eenvoudige regel niet uitvoerbaar is.\nLuister zonder meteen een oplossing te verkopen. Vat samen en controleer of u de taak goed begrijpt. Scheid het onderzoeken van oorzaken van het bespreken van een onmiddellijk gevaar. Veiligheid en respect zijn beide nodig: een zorgvuldig gesprek is geen reden om noodzakelijke bescherming uit te stellen.', practice: 'Een monteur loopt om een afzetting heen om een gereedschapkast te bereiken. Hij zegt dat de officiële looproute langs een afgesloten deur voert en daarom tijdens onderhoud niet bruikbaar is.', application: 'Vraag welke route bij verschillende onderhoudssituaties beschikbaar is en wie daarover beslist. Leg het knelpunt vast en onderzoek de inrichting, in plaats van alleen een extra nalevingsposter voor te stellen.' },
      { title: 'Signalen zijn geen metingen', explanation: 'Geur, geluid, trillingen of ervaren zwaarte kunnen aanleiding zijn tot onderzoek. Zij bewijzen niet automatisch dat een grenswaarde wordt overschreden of dat de situatie veilig is. Sommige schadelijke blootstellingen zijn niet zintuiglijk betrouwbaar waarneembaar.\nWeet wanneer u moet stoppen met zelf concluderen. Leg bron, taak, duur en maatregelen vast en schakel passende deskundigheid in. Geef geen numerieke risicoscore alleen omdat een formulier een getal verlangt. Een eerlijke open vraag ondersteunt een beter besluit dan schijnzekerheid.', practice: 'Bij reinigen ruikt een product sterk. Een collega wil direct noteren dat de blootstelling boven de norm ligt. Op een andere plek ruikt men niets en wil dezelfde collega de situatie veilig verklaren.', application: 'Gebruik beide observaties als aanleiding om stofinformatie en blootstellingsomstandigheden te onderzoeken. Vraag welke methode nodig is voor een verantwoord oordeel. Geur is geen zelfstandige grenswaardemeting.' },
      { title: 'Omgaan met mogelijk direct gevaar', explanation: 'Een rondgang kan een situatie opleveren waarbij wachten onaanvaardbaar lijkt. Volg dan de bestaande veilige werk- en escalatieafspraken: waarschuw betrokkenen, schakel de bevoegde verantwoordelijke in en voorkom dat u zelf technisch onbevoegd ingrijpt. Welke handeling passend is, hangt af van de situatie en uw taak.\nLeg daarna vast wat is waargenomen, wat direct is gedaan en welk vervolg nodig is. Het snelle ingrijpen vervangt de oorzaakanalyse en structurele oplossing niet. Omgekeerd mag een wens voor een compleet verslag geen reden zijn noodzakelijke actie uit te stellen.', practice: 'Tijdens een ronde draait een machine met een zichtbaar overbrugde beveiliging. U weet niet welke energiebronnen aanwezig zijn en bent niet bevoegd om aan de installatie te werken.', application: 'Ga niet zelf aan de bedrading sleutelen. Handel via de afgesproken veiligheidsprocedure en bevoegde lijn. Organiseer daarna technische beoordeling en een veilige storings- of onderhoudswerkwijze.' },
      { title: 'Van rondgang naar terugkoppeling', explanation: 'Maak een kort overzicht van bevinding, risico-informatie, ontbrekende gegevens en vervolg. Spreek af wie beoordeelt en beslist en hoe betrokkenen terughoren wat er gebeurt. Niet ieder punt is even urgent; dat vraagt een onderbouwde afweging en soms meer informatie.\nBespreek ook wat goed werkt, zodat effectieve oplossingen behouden blijven. Plan controle van uitvoering én effect. Een verzonden verslag is geen afgeronde verbetering. Houd onderscheid tussen “gesignaleerd”, “maatregel uitgevoerd” en “werking voldoende aangetoond”. Dat voorkomt een groen overzicht terwijl het probleem dagelijks terugkomt.', practice: 'Een rondgang levert vijftien punten op. De teamleider wil ze allemaal sluiten nadat zij de lijst heeft gedeeld. Twee punten vragen onderhoud, drie punten aanvullend onderzoek en enkele punten een eenvoudige opruimafspraak.', application: 'Beleg de verschillende vervolgen, maak prioriteit en onzekerheid zichtbaar en spreek een controlemoment af. Koppel aan medewerkers terug wat direct is opgelost en wat nog een besluit vraagt.' },
    ],
    exercises: ['U bereidt een ronde voor in een magazijn met wisselende laadpieken. Welke twee voorbereidingen helpen?', 'U ziet een kabel naast een intensief gebruikte doorgang. Welke notitie beschrijft de situatie feitelijk?', 'Uw inspecties zijn steeds in rustige uren terwijl de storingen in avonddienst ontstaan. Wat mist mogelijk?', 'U ziet bij onderhoud mogelijk direct gevaar aan een installatie. Welke eerste aanpak past?', 'Een medewerker wijkt tijdens drukte van de route af. Welke open vraag geeft inzicht?', 'Een checklist mist een relevant thuiswerksignaal. Wat doet u met het signaal?', 'Na de ronde staan meerdere punten open. Welke twee vervolgstappen zijn nodig?', 'Een sterke geur valt op bij een proces. Welke conclusie kunt u hieruit betrouwbaar trekken?', 'Bij een foto ontbreken tijdstip en taak. Waarom is die context nodig?'],
    summary: ['Bereid gericht voor en kijk naar relevante variatie in het werk.', 'Noteer feiten en onzekerheid; observeer niet alleen naleving.', 'Handel bij mogelijk direct gevaar via de passende veiligheidsafspraken.', 'Koppel terug en verbind bevindingen aan beoordeling, eigenaar en effectcontrole.'],
  },
  {
    title: 'Medewerkers betrekken en signalen herkennen',
    introduction: 'Veiligheidsinformatie ontstaat niet alleen in documenten. Medewerkers zien knelpunten, bijna-ongevallen en onwerkbare afspraken. Of die signalen u bereiken hangt af van vertrouwen, taal, tijd en opvolging. U leert informatie verzamelen zonder individuele gezondheid te diagnosticeren of een openbaar personeelsdossier op te bouwen.',
    objectives: ['Open gesprekken voeren over feitelijk werk en knelpunten.', 'Bijna-ongevallen en terugkerende signalen als onderzoeksvraag benutten.', 'Meldroutes en terugkoppeling praktisch organiseren.', 'Werkgerichte informatie onderscheiden van onnodige medische persoonsgegevens.'],
    legalContext: 'Wettelijke context: werknemersbetrokkenheid en passende informatievoorziening sluiten aan op het arbobeleid en de preventietaak. Persoonsgegevens, met name gezondheidsgegevens, vragen bijzondere zorgvuldigheid; een preventierol geeft geen algemene bevoegdheid tot medische registratie. Praktische aanbeveling: verzamel waar mogelijk werkgerichte of geaggregeerde informatie, maak het doel duidelijk en spreek af wie welke informatie nodig heeft.',
    lessons: [
      { title: 'Meldingen vertellen niet het hele verhaal', explanation: 'Veel meldingen kunnen wijzen op problemen, maar ook op vertrouwen in de meldroute. Weinig meldingen kunnen betekenen dat het goed gaat, dat medewerkers niet weten waar zij terechtkunnen of dat melden onveilig voelt. Trek dus niet direct een veiligheidsoordeel uit het aantal.\nCombineer meldingen met gesprekken, rondgangen en andere relevante gegevens. Vraag naar werkpatronen achter losse gebeurtenissen. Drie verschillende klachten over een moeilijk bereikbaar hulpmiddel kunnen op hetzelfde organisatorische knelpunt wijzen. Een signaal is het begin van onderzoek, niet de eindconclusie.', practice: 'In een productieteam worden nauwelijks bijna-ongevallen gemeld. Nieuwe medewerkers vertellen dat een melding in het werkoverleg vaak als persoonlijke fout wordt besproken.', application: 'Onderzoek het meldklimaat en bied een veilige manier om ervaringen te delen. Leg uit dat het doel leren en verbeteren is. Volg ook de gemelde technische of organisatorische problemen op; alleen vriendelijke communicatie is niet genoeg.' },
      { title: 'Open vragen en luisteren', explanation: 'Vraag naar concrete handelingen: wat gebeurt er, wanneer wijkt het af en wat maakt veilig werk lastig? Een vraag zoals “u gebruikt dit toch altijd?” nodigt uit tot bevestiging. Een vraag naar de laatste keer dat een hulpmiddel niet beschikbaar was, kan bruikbare informatie geven.\nLuisteren betekent niet iedere interpretatie als feit overnemen. Vat samen, vraag door op omstandigheden en controleer verschillende bronnen. Vermijd een ondervraging. Maak duidelijk wat u vastlegt en met wie u de informatie bespreekt. Zo groeit de kans dat ook ongemakkelijke ervaringen boven tafel komen.', practice: 'Een docent zegt dat de instructie voor verplaatsen van materiaal “niet werkt”. De leidinggevende wil het gesprek afsluiten omdat iedereen de instructie heeft ontvangen.', application: 'Vraag welke verplaatsing lastig is, hoeveel tijd en hulp beschikbaar zijn en wat er dan werkelijk gebeurt. Laat de docent een gewone werkdag beschrijven. Gebruik de uitkomst om de werkwijze en middelen te beoordelen.' },
      { title: 'Een bijna-ongeval als leerkans', explanation: 'Zonder letsel kan een gebeurtenis toch laten zien dat een barrière faalt. Beschrijf het verloop, omstandigheden en bestaande maatregelen. Vraag waarom het deze keer goed afliep en of u daarop de volgende keer kunt vertrouwen. Geluk is geen beheersmaatregel.\nVoorkom dat onderzoek uitsluitend op het laatste gedrag van één persoon eindigt. Kijk naar inrichting, planning, materialen, informatie en toezicht. Waar onmiddellijk gevaar speelt, handelt u eerst veilig. Onderzoek daarna systematisch welke verandering nodig is en wie daarover beslist.', practice: 'Een kar rijdt bijna tegen een collega in een zorggang. De kar is hoog beladen, een hoek is onoverzichtelijk en de levering vindt plaats tijdens de patiëntentransfers.', application: 'Onderzoek de combinatie van zicht, route en tijdstip. Een oproep “beter kijken” kan aanvullend zijn, maar verandert de belading of conflicterende verkeersstromen niet.' },
      { title: 'Verschillende stemmen bereiken', explanation: 'Niet iedere medewerker spreekt gemakkelijk in een groep. Taal, functie, tijdelijke inzet en afhankelijkheid kunnen meespelen. Bied passende kanalen, zoals een individueel werkgesprek, een toegankelijke meldroute of een kleine taakgerichte bespreking. Laat een leidinggevende niet automatisch namens alle medewerkers antwoorden.\nPas uitleg aan zonder de betekenis te versimpelen tot onjuiste geruststelling. Vraag medewerkers te laten zien of in eigen woorden te vertellen wat zij doen. Betrek ook schoonmaak, avondploegen en ingehuurde mensen als hun werkzaamheden relevante risico’s kennen.', practice: 'In een logistiek overleg reageren vooral twee ervaren medewerkers. Tijdelijke krachten begrijpen de technische woorden niet goed en knikken. Hun werk is juist het laden van containers buiten de vaste route.', application: 'Bespreek die taak apart en in begrijpelijke vorm. Gebruik een demonstratie en vraag naar afwijkingen tijdens drukte. Controleer of de vaste route ook voor hen uitvoerbaar en bekend is.' },
      { title: 'Gezondheidssignalen zonder medische dossiers', explanation: 'Een medewerker kan pijn, vermoeidheid of een diagnose noemen. Voor uw preventietaak is vooral relevant welke handelingen en omstandigheden aandacht vragen. U stelt geen medische oorzaak vast en deelt geen diagnoses in een algemeen actieoverzicht. Verwijs waar nodig naar bedrijfsarts of andere passende zorg.\nOok wanneer iemand informatie vrijwillig vertelt, hoeft u die niet volledig te registreren. Beperk het verslag tot het noodzakelijke werkknelpunt. Bespreek hoe u terugkoppelt en voorkom dat een klein team via details toch onnodig herleidbare gezondheidsinformatie krijgt. Vraag bij twijfel passende privacy- of medische expertise.', practice: 'Een medewerker vertelt uitgebreid over een behandeling en vraagt of u dit in de teamrapportage wilt opnemen om een beter bureau te krijgen. U heeft genoeg informatie om de werkopstelling te laten beoordelen zonder de diagnose te delen.', application: 'Leg de taak, werkopstelling en gevraagde beoordeling vast. Bespreek de route voor individuele ondersteuning apart. Gebruik geen medische details als overtuigingsmiddel in een openbaar teamoverzicht.' },
      { title: 'Terugkoppeling maakt melden zinvol', explanation: 'Een goede meldroute vertelt ook wat na melden gebeurt. Bevestig ontvangst, maak duidelijk wie onderzoekt en wanneer een vervolgbericht komt. Als een oplossing nog niet bekend is, kunt u wel uitleggen welke stap loopt en welke bescherming is afgesproken.\nSluit een melding niet alleen administratief. Vraag na uitvoering of het knelpunt in het werk verminderd is. Bewaar relevante historie volgens de bestaande afspraken, zodat terugkerende problemen zichtbaar blijven. Deel resultaten met de juiste mensen, niet automatisch met iedereen die toegang tot een algemeen systeem heeft.', practice: 'Een monteur heeft drie keer gemeld dat een hulpmiddel ontbreekt. Er is nu een extra exemplaar gekocht, maar de opslag ligt nog steeds te ver weg voor spoedwerk.', application: 'Koppel de aankoop terug en controleer praktisch gebruik. Onderzoek bereikbaarheid en planning en stel de oplossing bij. De derde melding was niet “dubbel” als het oorspronkelijke knelpunt nog bestond.' },
    ],
    exercises: ['Een zorgmedewerker meldt een bijna-val zonder letsel. Waarom is dit toch relevante informatie?', 'Een meldapp is beschikbaar maar medewerkers horen nooit iets terug. Welke twee verbeteringen helpen?', 'In een schoolteam komen weinig werkdrukmeldingen binnen. Welke conclusie is verantwoord?', 'U wilt weten waarom een zware taak zonder hulp wordt gedaan. Welke vraag opent het gesprek?', 'Een medewerker noemt een diagnose bij een werkplekprobleem. Wat hoort in het preventieverslag?', 'Na een aankoop blijft een melder hetzelfde knelpunt ervaren. Welke opvolging past?', 'Een nieuwe collega begrijpt de instructietaal beperkt. Hoe onderzoekt u praktisch begrip?', 'Een aantal signalen wijst op terugkerende routeproblemen. Welke signalen kunnen vervolgonderzoek rechtvaardigen?', 'Tijdens een teamgesprek zwijgen tijdelijke krachten. Hoe kunt u hun ervaringen zorgvuldig bereiken?'],
    summary: ['Een signaal is aanleiding tot onderzoek, geen diagnose of schuldconclusie.', 'Combineer bronnen en kijk ook naar het meldklimaat.', 'Vraag naar omstandigheden en bereik verschillende groepen.', 'Beperk persoonsgegevens en koppel terug wat met signalen gebeurt.'],
  },
  {
    title: 'Voorlichting, instructie en veilig gedrag',
    introduction: 'Goede uitleg helpt alleen als medewerkers die begrijpen en in hun werk kunnen toepassen. U leert de verbinding maken tussen risico, instructie, oefenen, middelen en toezicht. Veilig gedrag is daarmee geen losse karaktereigenschap, maar onderdeel van een werkbaar systeem.',
    objectives: ['Informatie, instructie en beheersing van een handeling onderscheiden.', 'Uitleg afstemmen op taak, risico en mogelijkheden van de medewerker.', 'Ook tijdelijke medewerkers en afwijkende situaties meenemen.', 'Toepassing na een instructie evalueren zonder alleen op handtekeningen te vertrouwen.'],
    legalContext: 'Wettelijke context: artikel 8 Arbowet betreft doeltreffende voorlichting en onderricht over werkzaamheden, risico’s en maatregelen, aangepast aan de taak en mogelijkheden, met passend toezicht. Een ontvangsthandtekening vervangt dit niet. Praktische aanbeveling: laat de veilige uitvoering voordoen, bespreek afwijkingen en controleer later de toepassing. De vorm en frequentie volgen uit werk en risico, niet uit een universeel jaarlijks toolboxaantal.',
    lessons: [
      { title: 'Wat moet iemand weten en kunnen?', explanation: 'Begin bij de handeling en het risico. Wat moet de medewerker herkennen, uitvoeren en nalaten? Wanneer moet hij stoppen en hulp vragen? Maak de inhoud concreet genoeg om in het werk te gebruiken. Een algemene presentatie over veiligheid is niet altijd voldoende voor een specifieke taak.\nMaak onderscheid tussen informeren en vaardigheid opbouwen. Weten waar de instructie staat is iets anders dan veilig een storing afhandelen. Bepaal welke oefening en begeleiding nodig zijn en wie kan beoordelen of de medewerker de taak beheerst. Trek geen bevoegdheidsgarantie uit aanwezigheid alleen.', practice: 'Een werkplaats introduceert een nieuw snijgereedschap. Medewerkers krijgen een folder, maar weten niet hoe zij het veilig afstellen of wat zij moeten doen als materiaal vastloopt.', application: 'Maak de handelingen en grenzen expliciet. Demonstreer, laat oefenen onder passende begeleiding en bespreek storingen. Laat technische werkzaamheden alleen uitvoeren door mensen met passende taak en deskundigheid.' },
      { title: 'Begrip zichtbaar maken', explanation: 'Vraag niet alleen of alles duidelijk is. Laat een medewerker de aanpak in eigen woorden uitleggen en waar passend voordoen. Dat geeft informatie over begrip en praktische uitvoerbaarheid. Formuleer het als ondersteuning, niet als poging iemand te betrappen.\nEen fout tijdens oefenen is informatie voor betere uitleg of inrichting. Onderzoek waarom de handeling niet lukt. Soms is de instructie onduidelijk; soms past het hulpmiddel niet of ontbreekt een voorwaarde. Houd de controle proportioneel en verbonden met het risico.', practice: 'Na een tilinstructie zegt iedereen het te begrijpen. Bij het oefenen blijkt dat de zorgmedewerkers het hulpmiddel niet onder het beschikbare bed kunnen positioneren.', application: 'Herhaal niet alleen de presentatie. Onderzoek de combinatie van bed, hulpmiddel en werkruimte en organiseer een passende werkwijze. Een extra handtekening verandert de technische beperking niet.' },
      { title: 'Begrijpelijke en passende communicatie', explanation: 'Taalniveau, ervaring en taak verschillen. Gebruik duidelijke woorden, een demonstratie en korte stappen waar dat helpt. Leg noodzakelijke vaktermen uit in relatie tot de werkhandeling. Vermijd dat visuele informatie de enige drager is; een afbeelding of kleur moet begrijpelijke uitleg ondersteunen.\nBij tijdelijke of nieuwe medewerkers is de behoefte vaak direct aanwezig. Veronderstel niet dat een andere werkgever alle lokale risico’s al heeft behandeld. Organiseer informatie, middelen en waar nodig begeleiding voor de feitelijke werkzaamheden en omstandigheden.', practice: 'Een uitzendkracht begint voor één avond bij een distributiecentrum. Hij kent algemene magazijnregels, maar niet de plaatselijke verkeerszones en stopprocedure bij geblokkeerde laadpoorten.', application: 'Regel lokale uitleg vóór inzet en begeleiding waar nodig. Controleer begrip van routes en afwijkingen. De korte inzetduur vermindert de noodzaak van passende bescherming niet.' },
      { title: 'Gedrag bekijken in het werksysteem', explanation: 'Een medewerker kan de veilige werkwijze kennen en toch anders handelen. Onderzoek wat die keuze beïnvloedt: tijd, bereikbaarheid van hulpmiddelen, tegenstrijdige opdrachten of een inrichting die omwegen veroorzaakt. Dit onderzoek vervangt geen aanspreken op gedrag, maar voorkomt een eenzijdige oplossing.\nVraag welk gedrag u verwacht en of de organisatie dat praktisch mogelijk maakt. Combineer waar nodig technische maatregelen, werkafspraken, instructie en toezicht. Een poster over oplettendheid kan ondersteunen, maar is geen vervanging voor een veilig werkproces.', practice: 'Technici dragen materialen via een korte onveilige doorgang omdat de veilige route tijdens leveringen is afgesloten. De vorige twee toolboxen veranderden dit niet.', application: 'Onderzoek de route- en leverafspraken en regel een bruikbaar alternatief. Bespreek daarna de veilige handeling en wat te doen als de route opnieuw niet beschikbaar is.' },
      { title: 'Afwijkingen en grenzen oefenen', explanation: 'Storingen, schoonmaak en spoedwerk wijken af van normaal gebruik. Een instructie moet waar relevant ook duidelijk maken wat een medewerker juist niet zelf mag doen en hoe hulp wordt ingeschakeld. Laat niet iedereen improviseren zodra de gewone stappen stoppen.\nVraag of de nood- en escalatieafspraken praktisch bereikbaar zijn tijdens iedere dienst. Wie neemt op, welke bescherming is nodig en wie beslist over hervatten? De preventiemedewerker kan dit helpen organiseren maar verleent geen nieuwe technische bevoegdheden door een instructiekaart te schrijven.', practice: 'Bij vastgelopen materiaal opent een medewerker een afscherming omdat de productiestap anders niet verder kan. De storingsinstructie noemt alleen een telefoonnummer dat in de nachtdienst niet wordt opgenomen.', application: 'Laat de technische veiligheid en storingsprocedure beoordelen. Regel een werkbare lijn voor alle diensten en oefen herkenning van de grens waarop stoppen en hulp nodig zijn.' },
      { title: 'Toepassing volgen en instructie actualiseren', explanation: 'Controleer na verloop van tijd of de werkwijze onder normale omstandigheden wordt toegepast. Gebruik observaties en gesprekken, niet alleen een online aanwezigheidsoverzicht. Verandert het werk of een hulpmiddel, beoordeel dan ook de instructie.\nEen herhaling is zinvol als deze aansluit op een concreet knelpunt of veranderde taak. Kies niet automatisch een langere presentatie wanneer de oorzaak in materiaal of planning ligt. Houd passende registratie van inhoud en deelnemers bij, maar laat die de inhoudelijke effectcontrole niet vervangen.', practice: 'In een kantoororganisatie heeft iedereen een ergonomiesessie gevolgd. Nieuwe medewerkers ontvangen de uitleg niet en bestaande bureaus worden na verhuizingen niet opnieuw passend ingesteld.', application: 'Neem instructie op in het inwerken en bij veranderingen en controleer instellingen in de praktijk. Zo wordt kennis onderdeel van een terugkerende werkwijze in plaats van een eenmalige bijeenkomst.' },
    ],
    exercises: ['Een presentielijst is compleet, maar niemand heeft de uitvoering bekeken. Welk bewijs ontbreekt?', 'Een team krijgt een nieuwe snijmachine. Welke instructieonderdelen zijn bruikbaar?', 'Medewerkers kennen de instructie maar kunnen het hulpmiddel niet bereiken. Wat onderzoekt u?', 'Na een uitleg wilt u weten of de handeling wordt beheerst. Welke methode helpt?', 'Een uitzendkracht werkt één dienst in dezelfde risicovolle zones. Welke lokale aanpak past?', 'Een werkproces verandert. Waarop moet de nieuwe instructie-inhoud worden gebaseerd?', 'Een regel is lastig te volgen bij het normale werktempo. Welke organisatorische factoren ondersteunen veilig werk?', 'Een toolbox van tien minuten blijkt onvoldoende voor een complexe taak. Waarom kan dat?', 'Een onbekende vakterm blokkeert begrip bij nieuwe medewerkers. Hoe maakt u deze bruikbaar?'],
    summary: ['Vertrek vanuit risico, taak en benodigde vaardigheid.', 'Demonstreer en controleer begrip en toepassing.', 'Maak veilig werk uitvoerbaar met middelen en organisatie.', 'Betrek nieuwe en tijdelijke medewerkers en afwijkende situaties.'],
  },
  {
    title: 'Maatregelen uitvoeren, controleren en opvolgen',
    introduction: 'Een maatregel is pas waardevol als zij in het werk bescherming geeft. Dit hoofdstuk leert u onderscheid maken tussen bestellen, uitvoeren, gebruiken, effect aantonen en borgen. U oefent ook omgaan met vertraging en onverwachte neveneffecten.',
    objectives: ['Uitvoering onderscheiden van effectiviteit en borging.', 'Een passende effectcontrole voorbereiden met verantwoordelijke en moment.', 'Vertraging en tijdelijke bescherming opvolgbaar maken.', 'Maatregelen evalueren bij verschillende taken en gebruikers.'],
    legalContext: 'Wettelijke context: de werkgever moet passende maatregelen organiseren en RI&E/PvA bijhouden waar nodig. Een afgeronde aankoop neemt die zorg niet over. Praktische aanbeveling: leg vooraf een effectcriterium, controle en beheerafspraak vast. Waar technische of blootstellingsdeskundigheid nodig is, laat de preventiemedewerker geen ongefundeerd eigen eindoordeel geven.',
    lessons: [
      { title: 'Vier verschillende voortgangsvragen', explanation: 'Is de maatregel afgesproken? Is zij uitgevoerd? Wordt zij gebruikt en werkt zij? Is de werking duurzaam georganiseerd? Deze vragen kunnen verschillende antwoorden hebben. Een afzuiger kan geïnstalleerd zijn terwijl de kap te ver van de bron staat. Een instructie kan gegeven zijn terwijl een hulpmiddel niet beschikbaar is.\nMaak het overzicht eerlijk. Gebruik status en toelichting die duidelijk maken wat nog moet worden aangetoond. Een groene aankoopactie kan naast een open effectcontrole bestaan. Zo voorkomt u dat een administratief succes het resterende risico verbergt.', practice: 'Een productieafdeling meldt “stofprobleem opgelost” na installatie van afzuiging. De operator zegt dat de arm niet bij de bewerkingsplek kan komen als een groot product wordt gemaakt.', application: 'Controleer de werking onder die relevante conditie met passende expertise. Houd het risico en de effectcontrole open totdat een verantwoorde conclusie mogelijk is. De levering alleen is geen voldoende resultaat.' },
      { title: 'Effectcriteria vooraf kiezen', explanation: 'Vraag vóór uitvoering waaraan u wilt merken dat de maatregel helpt. Kies een criterium dat verbonden is met het risico, zoals aantoonbaar verminderde blootstelling of gescheiden verkeersstromen tijdens pieken. Alleen tellen hoeveel posters zijn opgehangen of mensen zijn getraind meet vooral activiteit.\nBepaal welke methode nodig is. Soms volstaan passende observaties en gesprekken; soms zijn metingen of specialistische beoordeling nodig. Beschrijf representatieve omstandigheden en beperkingen. Een tevreden team kan nuttige informatie geven, maar is niet voor iedere blootstellingsvraag een zelfstandig veiligheidsbewijs.', practice: 'Een magazijn voert gescheiden routes in. De projectgroep wil succes meten aan het aantal uitgedeelde plattegronden. De bijna-botsingen vonden juist bij een smalle laadhoek plaats.', application: 'Controleer of de verkeersstromen ook in de laadhoek en bij drukte gescheiden blijven. Neem routegebruik, uitzonderingen en opvolging van blokkades mee. Plattegronden kunnen instructie ondersteunen maar meten het effect niet.' },
      { title: 'Gebruik en bruikbaarheid onderzoeken', explanation: 'Een maatregel moet passen bij handeling, ruimte en gebruiker. Vraag waarom zij niet wordt gebruikt en bekijk de taak. Het kan gaan om ontbrekende instructie, maar ook om een technisch ongeschikt middel, tijdsdruk of slecht beheer. Stel niet vooraf één oorzaak vast.\nMaak gebruikers onderdeel van de evaluatie. Zij kunnen laten zien op welk moment een oplossing niet meer werkt. Blijf daarbij risico en deskundigheid bewaken: de meest populaire optie is niet automatisch veilig. Combineer praktijkkennis met een onderbouwde beoordeling.', practice: 'In de zorg blijft een nieuw transferhulpmiddel vaak in de gang staan. Het team zegt dat de oplaadplek ver van de kamers ligt en de accu tijdens de drukste periode leeg is.', application: 'Onderzoek beschikbaarheid, opladen, onderhoud en werkplanning. Regel wie de gereedheid controleert en beoordeel of het hulpmiddel voor de relevante transfers passend blijft.' },
      { title: 'Vertraging en tijdelijke bescherming', explanation: 'Een vertraagde actie vraagt meer dan een nieuwe einddatum. Bespreek waarom uitvoering niet lukt, wie moet besluiten en hoe het risico intussen wordt beheerst. Een tijdelijke maatregel hoort een bewuste scope en controle te hebben; zij mag niet ongemerkt de ononderbouwde permanente situatie worden.\nMaak duidelijk welke informatie of expertise voor de afweging nodig is. Beleg het besluit bij de verantwoordelijke en leg vervolg en controlemoment vast. De preventiemedewerker volgt op en adviseert, maar neemt niet stilzwijgend het risico van een managementbesluit over.', practice: 'Een geluidsreducerende omkasting komt later. De tijdelijke werkwijze is gebaseerd op kort gebruik, maar de productie is inmiddels verdubbeld.', application: 'Laat de gewijzigde blootstelling en tijdelijke bescherming opnieuw beoordelen. Een oudere afspraak kan buiten haar aannames vallen. Bespreek maatregelen en productieplanning met de verantwoordelijke werkgever en passende deskundige.' },
      { title: 'Neveneffecten en variatie', explanation: 'Een oplossing kan een ander risico vergroten: een tilhulp blokkeert een route, afscherming belemmert onderhoud of een nieuwe stof heeft andere gebruikseisen. Beoordeel de oplossing in het werkproces en niet alleen op het oorspronkelijke probleem.\nDenk ook aan verschillende groepen en diensten. Wat in een pilot met twee ervaren medewerkers werkt, kan anders uitpakken bij tijdelijk personeel, schoonmaak of nachtwerk. Een pilot ondersteunt leren; zij is geen garantie voor iedere situatie. Beschrijf daarom welke variatie nog moet worden gecontroleerd.', practice: 'Een technische dienst gebruikt een mobiele tafel die tillen vermindert. Bij opladen staat deze naast een nooduitgang. De proefopstelling keek alleen naar de werkhoogte overdag.', application: 'Neem parkeren, laden en routes mee in de evaluatie. Zoek een oplossing die beide risico’s beheerst en controleer de nieuwe afspraak onder relevante omstandigheden.' },
      { title: 'Beheer en afwijkingsopvolging', explanation: 'Borging vraagt een eigenaar voor dagelijks gebruik, onderhoud, controles en opvolging van storingen. Een maatregel die niemand beheert kan langzaam uitvallen zonder dat het PvA dat toont. Maak instructie en beheer vindbaar voor vervangers en nieuwe medewerkers.\nSluit een actie inhoudelijk af met een vastgelegd resultaat en restpunten. Bepaal wanneer opnieuw wordt gekeken en welke verandering een tussentijdse beoordeling vraagt. Daarmee loopt de lijn terug naar RI&E en planning. De volgende hoofdstukken behandelen de samenwerking en organisatie die dit mogelijk maken.', practice: 'Een afzuiginstallatie werkt na oplevering goed. Zes maanden later is onduidelijk wie filters controleert en wat operators moeten doen als de indicator afwijkt.', application: 'Leg beheer, controle en storingsmelding vast met de betrokken verantwoordelijken. Instrueer gebruikers en neem de controle op in bestaande onderhouds- of werkafspraken. Bewaar het oorspronkelijke effectbewijs met zijn scope.' },
    ],
    exercises: ['Een afzuiger is geplaatst en gefactureerd. Wanneer kan de risicoactie inhoudelijk worden afgerond?', 'Een technische maatregel werkt nu goed. Welke beheerafspraken zijn nodig?', 'Een transferhulpmiddel wordt weinig gebruikt. Welke eerste onderzoeksvraag past?', 'Een verkeersmaatregel moet worden geëvalueerd. Welke indicator kijkt naar effect?', 'Bij storingen wordt een beschermkap geopend. Welke vervolgaanpak is passend?', 'De tijdelijke bescherming past niet meer bij de actuele productie. Wat vraagt dit?', 'Een project levert een hulpmiddel aan een team over. Welke twee onderdelen helpen?', 'Een oplossing introduceert een nieuw knelpunt in de looproute. Wat moet in de evaluatie gebeuren?', 'Een voortgangsoverleg blijft bij algemene intenties. Wat maakt de opvolging concreet?'],
    summary: ['Uitgevoerd is niet hetzelfde als effectief en geborgd.', 'Kies een controle die past bij risico en werkcondities.', 'Onderzoek bruikbaarheid en neveneffecten met gebruikers.', 'Beleg beheer en maak vertraging en restpunten zichtbaar.'],
  },
  {
    title: 'Samenwerken met werkgever, OR/PVT en deskundigen',
    introduction: 'De preventiemedewerker werkt tussen praktijkkennis, werkgeversbesluiten, medezeggenschap en specialistische expertise. Dit hoofdstuk helpt u de verbinding organiseren zonder rollen te verwarren. Samenwerken betekent niet dat iedereen hetzelfde moet doen, maar dat informatie, besluit en uitvoering elkaar bereiken.',
    objectives: ['De rollen van werkgever, OR/PVT en deskundigen in preventie onderscheiden.', 'De medezeggenschap tijdig en passend betrekken.', 'Een deskundigheidsvraag afbakenen en bruikbare informatie delen.', 'Adviezen vertalen naar werkbare besluiten en opvolging.'],
    legalContext: 'Wettelijke context: artikel 13 noemt advisering en samenwerking met OR/PVT en deskundigen en betrokkenheid bij persoon en positie. Concrete medezeggenschapsrechten en overlegverplichtingen moeten op de eigen situatie worden toegepast. Medische vertrouwelijkheid blijft gescheiden van algemene preventierapportage. Praktische aanbeveling: spreek overleg, scope, besluitvorming en terugkoppeling expliciet af; een externe adviseur neemt werkgeversverantwoordelijkheid niet automatisch over.',
    lessons: [
      { title: 'Rollen op één kaart', explanation: 'De werkgever beslist over beleid, organisatie en middelen binnen de toepasselijke verplichtingen. Medewerkers kennen het werk. OR/PVT vervult een eigen medezeggenschapsrol. Deskundigen bieden kennis binnen hun scope. De preventiemedewerker verbindt, adviseert en ondersteunt uitvoering.\nMaak bij ieder vraagstuk duidelijk welke rol nodig is. Een advies kan technisch sterk zijn en toch een besluit over capaciteit of planning vragen. Een medewerkersvoorkeur kan praktisch belangrijk zijn en toch deskundige beoordeling nodig hebben. Duidelijke rollen voorkomen dat iedereen naar een ander verwijst.', practice: 'Een extern rapport adviseert een andere opslagmethode. De teamleider wacht op de preventiemedewerker, de preventiemedewerker op de adviseur en de adviseur op een budgetbesluit.', application: 'Maak de besluitlijn expliciet: wie beoordeelt de maatregel, wie beslist over middelen, wie organiseert uitvoering en wie controleert de werking? Leg de open vraag aan de juiste partij voor.' },
      { title: 'Medezeggenschap tijdig betrekken', explanation: 'Betrokkenheid van OR/PVT is meer dan een rapport achteraf mailen. Persoon en positie van de preventiemedewerker hebben een specifieke wettelijke context. Ook in de inhoudelijke preventiepraktijk helpt tijdige uitwisseling om signalen en maatregelen beter te begrijpen.\nPas rechten zorgvuldig toe en doe geen algemene uitspraak voor iedere organisatievorm. Ontbreekt een OR/PVT, onderzoek welke overlegvorm en wettelijke vereisten wel gelden. Negeer werknemers niet omdat een bepaald orgaan ontbreekt. Markeer een onduidelijke juridische toepassing als vraag voor deskundige review.', practice: 'Een werkgever heeft een kandidaat gekozen en wil eerst benoemen en daarna de OR informeren. In de organisatie is onduidelijk welke rolafspraken zijn gemaakt.', application: 'Ga de toepasselijke instemmingsprocedure en betrokkenheid bij persoon en positie na voordat de procedure als afgerond wordt beschouwd. Bespreek ook de praktische samenwerking, tijd en rapportagelijn.' },
      { title: 'Een scherpe opdracht aan een deskundige', explanation: 'Formuleer de vraag vanuit het probleem en het besluit dat nodig is. Geef context over taken, betrokken groepen, blootstelling, bestaande maatregelen en onzekerheid. Vraag welke expertise en methode passend zijn en welke informatie nog nodig is.\nSpreek af wat het onderzoek wel en niet behandelt en hoe beperkingen worden gerapporteerd. Een brede titel op een offerte vervangt geen duidelijke scope. Vraag niet alleen bevestiging van de al gewenste oplossing. Onderzoek moet een verantwoord besluit ondersteunen, ook wanneer de uitkomst andere maatregelen vraagt.', practice: 'Een productieteam wil een adviseur laten bevestigen dat de bestaande afzuiging voldoende is. Er zijn alleen foto’s beschikbaar, geen gegevens over taken, gebruik of onderhoud.', application: 'Herschrijf de opdracht naar een beoordelingsvraag met relevante werkcondities. Laat de adviseur aangeven welke informatie en welk onderzoek nodig zijn om een uitspraak te kunnen onderbouwen.' },
      { title: 'Werk en gezondheid zorgvuldig verbinden', explanation: 'Een bedrijfsarts kan werkgerelateerde gezondheidssignalen helpen duiden binnen zijn eigen rol. De preventiemedewerker kan taken en omstandigheden toelichten en aanbevelingen helpen vertalen naar werkmaatregelen. Dat vraagt geen algemene toegang tot individuele diagnoses.\nStem af welke informatie nodig is en via welke lijn zij wordt gedeeld. Gebruik waar passend geaggregeerde of taakgerichte informatie. Medische en persoonlijke gegevens worden niet vanzelf onderdeel van RI&E of een teamrapport. Ook in een klein team verdient herleidbaarheid aandacht.', practice: 'Een school wil alle diagnoses van uitgevallen medewerkers verzamelen om de RI&E vollediger te maken. De bedrijfsarts vraagt juist om informatie over taken, roosters en werkdruksignalen.', application: 'Organiseer de werkgerichte informatie en bespreek met de passende professionals welke conclusies voor preventie bruikbaar zijn. Neem geen medische dossierfunctie over.' },
      { title: 'Advies vertalen zonder inhoud te verliezen', explanation: 'Een advies moet in de organisatie uitvoerbaar worden gemaakt. Bespreek met gebruikers wat de toepassing vraagt en met de deskundige welke voorwaarden essentieel zijn. Praktische bezwaren zijn relevante informatie, geen reden om een risico weg te stemmen.\nWanneer adviezen verschillen, vergelijk vraagstelling, scope en aannames. Middel geen conclusies zonder begrip en kies niet automatisch het goedkoopste rapport als inhoudelijk juist. Zorg dat de werkgever een onderbouwd besluit kan nemen met zicht op onzekerheid en restpunten.', practice: 'Twee adviseurs beoordelen een technische handeling verschillend. Het ene rapport gaat uit van kort incidenteel gebruik; het andere van dagelijks langdurig werk. De projectgroep wil het gemiddelde van beide scores nemen.', application: 'Laat de uitgangspunten verduidelijken en vergelijk die met het echte werk. Een verschil in context kan het verschil in uitkomst verklaren. Gebruik daarna een passende beoordeling voor het eigen proces.' },
      { title: 'Overleg dat tot besluiten leidt', explanation: 'Een vast overleg helpt risico’s, acties en middelen verbinden. Bereid een beperkte agenda voor met noodzakelijke besluiten en informatie. Benoem welke actie loopt, wat vastzit en welk vervolg nodig is. Houd urgente situaties buiten het wachten op een periodiek overleg.\nMaak achteraf duidelijk wie wat doet en wanneer wordt teruggekoppeld. Informeer medewerkers en medezeggenschap passend over relevante uitkomsten. Het doel is niet zoveel mogelijk vergaderen, maar dat signalen tot uitvoering en leren leiden.', practice: 'Het maandoverleg bestaat uit een presentatie van afgeronde acties. Open risico’s verdwijnen uit beeld omdat ze de vergadering langer maken.', application: 'Breng relevante vertragingen en besluiten terug op de agenda, met prioriteit en benodigde ondersteuning. Deel een beknopte opvolglijst met eigenaren en controlemomenten.' },
    ],
    exercises: ['Een werkgever wil een kandidaat benoemen voordat de OR bij persoon en positie wordt betrokken. Welk recht vraagt aandacht?', 'Voor overleg met de bedrijfsarts zijn werkvragen en medische dossiers door elkaar geraakt. Welke twee uitgangspunten passen?', 'Een adviseur heeft een maatregel aanbevolen. Wie beslist binnen de organisatie over uitvoering en middelen?', 'Er is geen OR/PVT en de werkgever wil daarom alle werknemersbetrokkenheid schrappen. Wat moet worden nagegaan?', 'Een rapport is niet werkbaar tijdens nachtdiensten. Welke gezamenlijke vervolgstap past?', 'Een extern onderzoek heeft geen duidelijke vraagstelling. Welke startvraag helpt?', 'Een overleg maakt de preventiemedewerker tot vervangend arts en budgethouder. Welke rolafspraken voorkomen verwarring?', 'De OR ziet alleen afgeronde punten. Welke informatie ontbreekt mogelijk?', 'Twee adviezen verschillen door andere aannames. Hoe maakt u ze bruikbaar voor een besluit?'],
    summary: ['Verbind praktijkkennis, deskundig advies en werkgeversbesluiten.', 'Betrek OR/PVT tijdig en pas rechten situationeel correct toe.', 'Maak scope en beperkingen van onderzoek expliciet.', 'Houd medische vertrouwelijkheid en gerichte preventie-informatie uit elkaar.'],
  },
  {
    title: 'Grenzen van eigen deskundigheid herkennen',
    introduction: 'Een goede preventiemedewerker hoeft niet alles zelf te kunnen. Hij moet wel herkennen wanneer een eigen oordeel onvoldoende basis heeft. U leert onzekerheid formuleren, passende expertise kiezen en het proces gaande houden zonder medische of technische bevoegdheden te suggereren die u niet bezit.',
    objectives: ['Een deskundigheidsgrens onderscheiden van een administratief knelpunt.', 'Een open onderzoeksvraag met context en tijdelijke bescherming formuleren.', 'Scope en toepasbaarheid van rapporten kritisch lezen.', 'Medische, technische en formele toetsrollen zorgvuldig begrenzen.'],
    legalContext: 'Wettelijke context: artikel 13 verlangt passende deskundigheid en mogelijkheden voor de preventietaak; specialistische risico’s en formele toetsing kennen eigen vereisten. Een cursusnaam of leveranciersclaim bewijst niet dat iedere beoordeling mag worden uitgevoerd. Praktische aanbeveling: maak kennisgrenzen, onderzoeksvragen en onzekerheden zichtbaar en leg vast wie de passende expertise organiseert.',
    lessons: [
      { title: 'Twijfel herkennen als professioneel signaal', explanation: 'Twijfel kan ontstaan omdat gegevens ontbreken, een methode onbekend is of technische kennis niet bij de eigen taak past. Benoem precies welke vraag u niet kunt beantwoorden. “Ik weet niet of de beveiliging onder onderhoudsomstandigheden werkt” is bruikbaarder dan een algemeen gevoel van onveiligheid.\nEen grens erkennen is geen reden niets meer te doen. U kunt feiten verzamelen, betrokkenen waarschuwen binnen afspraken, de onderzoeksvraag helpen formuleren en opvolging organiseren. Vermijd een definitieve veiligheidsuitspraak om het proces administratief af te kunnen sluiten.', practice: 'Een ervaren preventiemedewerker kent de werkplaats goed, maar kan een gewijzigde machinebesturing niet beoordelen. De leverancier vraagt of hij het opleverformulier alvast wil tekenen als veilig.', application: 'Onderteken geen ongefundeerde veiligheidsconclusie. Leg de open beveiligingsvraag vast en laat passende technische expertise en bevoegdheid inzetten. Bespreek welke bescherming en voorwaarden tot die tijd nodig zijn.' },
      { title: 'Welke expertise past bij de vraag?', explanation: 'Kies expertise op inhoud, niet uitsluitend op een algemene titel. Een blootstellingsvraag kan andere kennis vragen dan ergonomie, machinebeveiliging of medezeggenschapsrecht. Vraag naar relevante ervaring, methode en scope en naar wat een deskundige niet onderzoekt.\nEen goede opdrachtgever geeft context en vraagt om begrijpelijke onderbouwing. De preventiemedewerker hoeft het onderzoek niet over te doen, maar moet wel weten welke conclusie voor welk werk geldt. Als een rapport niet aansluit op de vraag, bespreek dit voordat er uitvoering of afsluiting op wordt gebaseerd.', practice: 'Een organisatie vraagt een algemene adviseur of blootstelling bij een nieuw chemisch proces verantwoord is. De adviseur heeft vooral ervaring met kantoorwerkplekken en wil alleen een visuele ronde uitvoeren.', application: 'Bespreek de benodigde deskundigheid voor stoffen en blootstelling. Vraag welke informatie en methode nodig zijn en laat de opdracht zo nodig door een passende specialist uitvoeren.' },
      { title: 'Scope en aannames lezen', explanation: 'Een rapport heeft een onderwerp, omstandigheden, methode en beperkingen. Controleer of taak, duur, middelen en maatregelen overeenkomen met het werk waarvoor u het wilt gebruiken. Een gelijk adres of recente datum maakt de uitkomst niet automatisch passend.\nLet op wijzigingen sinds het onderzoek. Andere productie, stoffen of diensten kunnen buiten de eerdere aannames vallen. Leg vast wanneer een conclusie nog bruikbaar is en wanneer aanvullend onderzoek nodig wordt. Bewaar de historie zodat zichtbaar blijft waarom een eerdere keuze destijds passend leek.', practice: 'Een meetrapport gaat over tien minuten reinigen met middel A. Inmiddels gebruiken medewerkers middel B twee uur per dienst. De manager verwijst naar de rapportdatum van zes maanden geleden.', application: 'Beoordeel toepasbaarheid op de gewijzigde omstandigheden. Vraag passende deskundigheid naar de nieuwe blootstellingsvraag; pas een oude uitkomst niet stilzwijgend toe buiten de onderzochte scope.' },
      { title: 'Medische grenzen respecteren', explanation: 'Gezondheidsklachten kunnen een signaal voor werkonderzoek zijn. De preventiemedewerker stelt geen diagnose of behandeladvies vast en beoordeelt niet zelfstandig individuele medische beperkingen. Richt de eigen taak op werk, omstandigheden en mogelijke preventieve verbetering.\nVerwijs naar passende zorg of de bedrijfsarts waar dat aan de orde is. Verzamel niet automatisch diagnoses om een werkplekaanpassing te onderbouwen. Een verzoek om hulp is geen onbeperkte toestemming voor delen of opslaan van gezondheidsgegevens. Bewaak ook in mondeling overleg welke informatie noodzakelijk is.', practice: 'Een medewerker vraagt of zijn schouderpijn door het werk komt en welke behandeling hij moet volgen. U ziet dat de werkhoogte mogelijk ongunstig is maar bent geen medisch professional.', application: 'Onderzoek de werkhoogte als preventievraag en verwijs de medische vraag passend door. Leg geen eigen diagnose vast en koppel het werkplekonderzoek niet aan een ongefundeerde medische conclusie.' },
      { title: 'Onzekerheid vertalen naar handelen', explanation: 'Een onzeker resultaat kan betekenen dat meer gegevens nodig zijn of dat voorlopig voorzichtigere bescherming nodig is. Vraag de deskundige wat de bandbreedte betekent voor de beslissing. Presenteer de gunstigste mogelijkheid niet als zekerheid.\nMaak een open punt opvolgbaar met eigenaar en termijn. Beschrijf wat intussen wel en niet verantwoord is binnen de passende beoordeling. De preventiemedewerker organiseert duidelijkheid, maar beslist niet buiten zijn eigen taak over technisch of medisch veilige grenzen.', practice: 'Een onderzoek kan door wisselende productie nog geen representatief blootstellingsbeeld geven. De projectgroep wil de onzekerheidsparagraaf uit de samenvatting halen omdat deze de planning lastig maakt.', application: 'Houd de beperking zichtbaar en laat deskundig toelichten welke aanvullende gegevens of bescherming nodig zijn. Bespreek gevolgen voor planning en maatregelen met de verantwoordelijke werkgever.' },
      { title: 'Inspectie, advies en formele toetsing', explanation: 'Een werkplekinspectie kan een nuttige waarneming zijn. Een advies ondersteunt een besluit. Formele toetsing van de RI&E kent een eigen doel en vereisten. Deze activiteiten zijn niet uitwisselbaar omdat een externe partij ze uitvoert of een rapport ondertekent.\nControleer offerte en rapport op doel, scope en deskundigheid. Vraag bij twijfel wat juridisch nodig is. Deze opleiding geeft basis voor professionele preventieondersteuning, geen algemene erkenning als toetser. Heldere grenzen beschermen zowel medewerkers als de kwaliteit van uw eigen bijdrage.', practice: 'Een leverancier biedt een kort bezoek aan en noemt het “volledige RI&E-goedkeuring”. Het voorstel beschrijft alleen de zichtbare inrichting en bevat geen uitleg over de benodigde deskundigheid.', application: 'Laat verduidelijken welke activiteit werkelijk wordt geleverd en of die aan de benodigde toetsing voldoet. Bewaar de inhoudelijke en juridische vraag als open punt tot er een onderbouwde conclusie is.' },
    ],
    exercises: ['Een machinewijziging gaat buiten uw technische kennis. Wat is een professionele eerste aanpak?', 'Bij blootstelling ontbreken betrouwbare gegevens. Wanneer kan aanvullende expertise nodig zijn?', 'Een collega vraagt u een behandeling voor pijn voor te schrijven. Hoe begrenst u uw rol?', 'Een rapport voor een korte handeling wordt op een andere langdurige taak toegepast. Wat moet worden nagegaan?', 'Een rapport noemt relevante onzekerheid. Wat doet u met die informatie?', 'Een adviseur heeft een algemene titel, maar de taak vraagt specifieke blootstellingskennis. Welke vraag helpt?', 'U bereidt een deskundigenonderzoek voor. Welke twee soorten werkinformatie zijn bruikbaar?', 'U twijfelt aan de werking van een maatregel. Welke reactie past bij zorgvuldig handelen?', 'Een werkplekinspectie wordt verward met formele RI&E-toetsing. Welk onderscheid moet worden gemaakt?'],
    summary: ['Benoem precies wat u niet verantwoord kunt beoordelen.', 'Kies expertise op vraag en scope.', 'Begrijp beperkingen en behandel onzekerheid zichtbaar.', 'Ondersteun preventie zonder medische of formele toetsbevoegdheid te claimen.'],
  },
  {
    title: 'Jaarplanning, evaluatie en borging',
    introduction: 'Preventie moet blijven werken bij wisselende mensen, planningen en werkzaamheden. U leert een beperkt maar bruikbaar jaarritme maken dat risico’s en open acties volgt. De kalender helpt organiseren, maar bepaalt niet wanneer een nieuw risico aandacht verdient.',
    objectives: ['Een risicogestuurde planning maken met uitvoering en effectcontrole.', 'Activiteiten en resultaten onderscheiden in evaluaties.', 'Overdracht, beheer en inwerken als borgingsonderdelen organiseren.', 'Veranderingen verwerken zonder op een vaste kalendertermijn te wachten.'],
    legalContext: 'Wettelijke context: het arbobeleid en de RI&E moeten bij het werk en relevante veranderingen blijven passen. Een jaarlijkse agenda is een praktische organisatievorm, geen bewijs dat tussentijdse actualisatie overbodig is. Een certificaat van afronding heeft geen door kennisbehoud of jaarcheck verlengde wettelijke geldigheid. Praktische aanbeveling: combineer vaste evaluatiemomenten met duidelijke triggers voor tussentijdse aandacht.',
    lessons: [
      { title: 'Van risico naar jaarritme', explanation: 'Gebruik de RI&E, het PvA, meldingen en geplande veranderingen als vertrekpunt. Bepaal welke acties, controles en overlegmomenten nodig zijn en wie betrokken is. Plan niet alleen trainingen omdat die eenvoudig op een kalender passen.\nHoud de planning overzichtelijk en uitvoerbaar. Prioriteiten en capaciteit moeten aansluiten. Als niet alles tegelijk kan, maak een verantwoord besluit en tijdelijke bescherming zichtbaar. Een grote agenda zonder middelen is geen bewijs van georganiseerd preventiebeleid.', practice: 'Een school plant vier veiligheidsbijeenkomsten per jaar. De open actie over fysieke belasting en de controle van aangepaste opslag ontbreken in de agenda.', application: 'Voeg de noodzakelijke uitvoering en effectcontrole toe met eigenaar en moment. Koppel bijeenkomsten aan concrete kennis- of vaardigheidsvragen in plaats van een vast aantal als doel te nemen.' },
      { title: 'Activiteit is niet hetzelfde als resultaat', explanation: 'Het aantal rondes, instructies of verzonden berichten vertelt iets over inspanning. Het zegt niet automatisch dat blootstelling is verminderd of een veilige werkwijze bruikbaar is. Kies ook informatie over gebruik, werking en afwijkingen.\nCombineer bronnen. Een laag ongevalscijfer kan gunstig zijn, maar sluit onbeheerste risico’s niet uit. Goede effectcontrole kan ook naar bijna-ongevallen, onderhoud, blootstelling of representatieve observaties kijken. Pas de methode aan het risico aan en vermijd schijnzekerheid door één getal.', practice: 'Een productiebedrijf viert dat er zes maanden geen geregistreerd ongeval is. Medewerkers melden intussen geregeld uitval van een afzuiging en tijdelijke overbrugging van storingen.', application: 'Neem de signalen en werking van maatregelen mee in de evaluatie. Onderzoek de storingen en herstel de beheersing in plaats van het lage ongevalscijfer als sluitend bewijs te presenteren.' },
      { title: 'Beheer over mensen heen organiseren', explanation: 'Een maatregel moet ook blijven werken als de projectleider afwezig is of de preventiemedewerker vertrekt. Maak duidelijk waar afspraken staan en wie controleert en beslist. Leg niet alleen kennis vast, maar ook contactlijnen en de status van open punten.\nNeem veilig werken op in inwerk- en overdrachtsafspraken. Een nieuwe medewerker kent de reden van een maatregel niet vanzelf. Laat beheer bij een passende rol horen en niet alleen bij een persoon die toevallig gemotiveerd is. Zo wordt continuïteit onderdeel van de organisatie.', practice: 'Een kantoorteam gebruikt verstelbare hulpmiddelen. De collega die nieuwe medewerkers uitlegde hoe zij werden ingesteld, vertrekt. De instructie staat alleen in zijn persoonlijke map.', application: 'Draag uitleg, beheer en controle over aan een passende rol en maak de werkwijze vindbaar. Controleer bij nieuwe gebruikers of de inrichting passend en begrijpelijk is.' },
      { title: 'Wijzigingen als trigger gebruiken', explanation: 'Een verbouwing, andere bezetting, nieuw proces of nieuwe kennis kan tussentijdse aandacht vragen. Leg vast wie zulke veranderingen meldt en welke beoordeling nodig is vóór of tijdens invoering. Niet iedere verandering vraagt automatisch het hele beleid opnieuw, maar relevante gevolgen mogen niet buiten beeld blijven.\nKoppel dit aan de bestaande besluit- of projectprocessen. Vraag bij een wijziging naar werknemers, taken, blootstelling, benodigde instructie en beheer. Werk relevante onderdelen van RI&E en PvA bij. Een planning moet kunnen leren van veranderingen.', practice: 'Halverwege het jaar wordt een nieuwe avondploeg ingezet. De controles en instructies waren alleen voor de dagdienst georganiseerd. De jaarcontrole is een week eerder afgerond.', application: 'Beoordeel wat de andere dienst vraagt en regel bereikbaarheid van middelen, begeleiding en escalatie. Een recente controle voor andere omstandigheden geeft geen automatische dekking.' },
      { title: 'Herhaald uitstel bestuurlijk maken', explanation: 'Als een actie telkens verschuift, kan de oorzaak liggen in middelen, eigenaarschap of een ontbrekend besluit. Spreek niet alleen af dat “iedereen zijn best doet”. Maak het knelpunt concreet: wat is nodig, wat gebeurt intussen en wie moet kiezen?\nHoud de originele reden en voortgang herleidbaar. Vernieuw niet de code om ouderdom te verbergen en verlaag het risico niet om een planning passend te maken. De preventiemedewerker helpt de bestuurlijke vraag formuleren en bewaakt dat een inhoudelijk open risico niet stilzwijgend administratief verdwijnt.', practice: 'Een technische aanpassing wordt ieder kwartaal doorgeschoven. De uitvoerder heeft geen budgetbevoegdheid en de budgethouder is niet bij het overleg aanwezig.', application: 'Breng het noodzakelijke besluit naar de juiste verantwoordelijke met risico, opties, tijdelijke bescherming en termijn. Laat de uitkomst terugkomen in het actieoverzicht.' },
      { title: 'Evalueren en een volgende cyclus starten', explanation: 'Bespreek wat is uitgevoerd, wat aantoonbaar werkt, welke onverwachte effecten zijn ontstaan en welke informatie nog ontbreekt. Behoud effectieve afspraken en pas onwerkbare onderdelen aan. Een evaluatie is geen ritueel om alles groen te verklaren.\nLeg enkele concrete verbeterpunten vast en verbind ze aan de volgende periode. De cyclus kan ook buiten de jaargrens opnieuw beginnen. Leren uit werk is doorlopend; de kalender biedt structuur, geen vaste vervaldatum en geen vrijstelling van tussentijdse zorg.', practice: 'Een zorgorganisatie heeft een hulpmiddelproject afgerond. Tijdens de evaluatie blijkt dat de nachtploeg geen sleutels heeft voor de opslagruimte en de oude handeling blijft gebruiken.', application: 'Heropen het relevante uitvoeringspunt, regel toegankelijke opslag en controleer de toepassing. Actualiseer de afspraken en neem de les mee naar andere overdrachtsprocessen.' },
    ],
    exercises: ['Een jaaragenda bevat alleen overlegdata. Waarop moet een preventieplanning inhoudelijk worden gebaseerd?', 'U wilt de werking van het beleid evalueren. Welke onderdelen horen erbij?', 'De preventiemedewerker vertrekt terwijl acties lopen. Welke overdracht helpt continuïteit?', 'De managementrapportage telt alleen toolboxen. Wat onderscheidt een resultaatindicator?', 'Er zijn weinig ongevallen maar wel terugkerende blootstellingssignalen. Waarom is het cijfer alleen niet voldoende?', 'Een verbouwing wordt halverwege het jaar gepland. Wat gebeurt met de preventieagenda?', 'Een ergonomisch hulpmiddel is ingevoerd en er komen nieuwe gebruikers. Welke twee borgingsafspraken passen?', 'Een actie wordt steeds verschoven zonder onderbouwd besluit. Wat bespreekt u?', 'Een controleoverzicht bevat alleen vinkjes. Welke registratie maakt de controle herleidbaar?'],
    summary: ['Plan vanuit risico’s, acties en veranderingen.', 'Meet niet alleen inspanning maar ook bruikbaar resultaat.', 'Maak overdracht, beheer en instructie rolgebonden.', 'Gebruik evaluatie om gericht bij te stellen, ook buiten het jaarritme.'],
  },
  {
    title: 'Integrale praktijkcasus: preventiemedewerker in actie',
    introduction: 'U begeleidt de fictieve organisatie Werkstroom. Een techniek- en distributielocatie krijgt een nieuwe reinigingsstap, verandert routes en zet tijdelijk personeel in. De directie wil snel starten. Medewerkers melden knelpunten en de beschikbare informatie is onvolledig. U doorloopt de volledige preventiecyclus en houdt rollen, deskundigheid en borging bij elkaar.',
    objectives: ['Meerdere veranderingen vertalen naar een samenhangende preventieaanpak.', 'Ontbrekende informatie, deskundigheid en tijdelijke bescherming organiseren.', 'Werkgever, medewerkers, medezeggenschap en deskundigen doelgericht betrekken.', 'Uitvoering, effect en borging als één verbetercyclus evalueren.'],
    legalContext: 'Wettelijke context: werkgeversverantwoordelijkheid, RI&E/PvA, deskundige bijstand, werknemersbetrokkenheid en passende instructie blijven naast elkaar gelden. Een planning of opleidingscertificaat vervangt geen risicoafweging. Praktische aanbeveling: gebruik één samenhangend actieoverzicht met risico, vraag, maatregel, eigenaar, termijn, effectcontrole en beheer; dit specifieke format is geen algemene wettelijke vormeis.',
    lessons: [
      { title: 'Werkstroom: eerst een betrouwbaar beeld', explanation: 'De nieuwe reinigingsstap gebruikt een ander middel. Heftrucks rijden langs een tijdelijke opslag en uitzendkrachten beginnen in de avond. Bekijk deze veranderingen niet als drie losse documenten. Zij kunnen elkaar beïnvloeden: een andere opslagroute verandert blootstelling en een nieuw team heeft andere informatie nodig.\nVerzamel wat bekend is en wat nog niet. Vraag medewerkers van verschillende diensten hoe de taak verloopt. Koppel bronnen aan waarnemingen en beschrijf onzekerheid. De preventiemedewerker helpt dit proces organiseren en geeft niet alvast een definitieve veilige score om de startdatum te halen.', practice: 'De directie wil de oude RI&E op het nieuwe proces toepassen. Een medewerker meldt dat het middel handmatig wordt overgegoten vlak naast de voetgangersroute. De avondploeg is nog niet gesproken.', application: 'Onderzoek taak, stof, route, groepen en bestaande bescherming. Maak de ontbrekende informatie expliciet en bespreek welke specialistische beoordeling en tijdelijke afspraken nodig zijn vóór verdere inzet.' },
      { title: 'Beoordelen en deskundigheid organiseren', explanation: 'Splits de vragen zonder de samenhang te verliezen. De blootstellingsvraag kan specialistische expertise vragen. Verkeer vraagt een beeld van stromen, zicht en piekbelasting. Instructie vraagt inzicht in handelingen, taal en bereikbaarheid van begeleiding.\nLeg per vraag vast welke informatie nodig is en wie een verantwoord oordeel kan geven. Houd onzekerheid zichtbaar in het besluit. Een gunstige conclusie voor dagdienst kan niet zonder verdere onderbouwing voor de avond gelden. Breng de werkgever in positie om over bescherming, planning en middelen te beslissen.', practice: 'Een bestaand meetrapport beschrijft een ander reinigingsmiddel en korte gebruiksduur. De projectleider wil het rapport toch gebruiken omdat het dezelfde afdeling noemt.', application: 'Laat de toepasbaarheid beoordelen en organiseer aanvullend onderzoek waar nodig. Leg uit welk besluit nog niet onderbouwd is en welke tijdelijke bescherming of aanpassing van de invoering nodig kan zijn.' },
      { title: 'Maatregelen kiezen met de praktijk', explanation: 'Onderzoek mogelijkheden om de bron te veranderen, zoals een geschikter middel of gesloten werkwijze. Bekijk technische scheiding en een bruikbare verkeersinrichting. Organiseer daarna passende instructie en toezicht. Kies niet alleen wat het snelst op een poster past.\nBetrek gebruikers bij de uitvoerbaarheid en deskundigen bij de onderbouwing. Maak duidelijk wie beslist en welke voorwaarden essentieel zijn. Een voorkeur van medewerkers is belangrijke informatie, maar geen vervanging van een veiligheidsbeoordeling. Een technisch advies moet andersom vertaald worden naar werkbare routines.', practice: 'Een leverancier biedt een gesloten reinigingssysteem aan, maar de onderhoudsruimte is beperkt. Medewerkers vragen vooral een korte training en extra handschoenen omdat zij die oplossing kennen.', application: 'Onderzoek passendheid van het systeem, onderhoud en werkruimte en vergelijk de risicobeheersing. Regel benodigde bescherming tijdens de uitwerking. Presenteer de keuze met voorwaarden en restpunten aan de werkgever.' },
      { title: 'Uitvoering voor alle relevante groepen', explanation: 'Een maatregelenpakket moet ook beschikbaar zijn wanneer de projectgroep naar huis is. Regel lokale instructie en begeleiding voor tijdelijke werknemers. Maak routes, middelen en escalatie bereikbaar in alle relevante diensten. Een algemene instructie van een andere organisatie dekt niet automatisch het lokale werk.\nGebruik demonstratie en laat de handeling voordoen. Vraag wat gebeurt bij drukte, storing of een ontbrekend hulpmiddel. Verbind afwijkingen aan een veilige vervolgstap. De preventiemedewerker ondersteunt de organisatie hiervan, terwijl lijnverantwoordelijken de uitvoering passend beleggen.', practice: 'De dagploeg gebruikt de nieuwe route. De avondploeg vindt een deur gesloten en neemt de oude doorgang. De begeleider voor tijdelijke krachten is alleen overdag aanwezig.', application: 'Maak de route ook voor avondwerk bruikbaar en regel passende begeleiding en bereikbaarheid. Controleer begrip met de betrokken medewerkers en laat problemen terugkomen in het actieoverzicht.' },
      { title: 'Effect controleren onder echte omstandigheden', explanation: 'Na oplevering controleert u niet alleen of onderdelen aanwezig zijn. Kijk of de reiniging daadwerkelijk minder blootstelling geeft en of de stromen ook tijdens pieken gescheiden blijven. Gebruik passende expertise voor de blootstellingsbeoordeling. Neem ervaringen van vaste en tijdelijke medewerkers mee.\nOnderzoek neveneffecten, zoals opslag die een route blokkeert of onderhoud dat bescherming ondermijnt. Een deelresultaat is waardevol maar geen complete afronding. Leg vast wat voldoende is aangetoond en wat nog niet. Zo blijven beslissingen herleidbaar.', practice: 'De eerste week verloopt rustig. In week twee blijkt bij volle productie dat de gesloten installatie een extra handmatige stap vraagt en het verkeer weer kruist. Het projectverslag staat al op groen.', application: 'Beoordeel de gewijzigde handeling en verkeerssituatie opnieuw. Pas de maatregel of organisatie aan en controleer daarna opnieuw. Gebruik de ervaring om de voorwaarden van het eerdere resultaat te verduidelijken.' },
      { title: 'Borgen en terugkoppelen', explanation: 'Sluit af met beheer, instructie, onderhoud en afwijkingsopvolging. Beleg wie kijkt of de oplossing blijft werken en wie reageert op storingen of veranderingen. Werk RI&E en PvA bij met relevante uitkomsten en behoud open restpunten.\nKoppel aan medewerkers en medezeggenschap terug wat is geleerd en wat nog volgt. Een werkbare cyclus maakt niet ieder risico definitief verdwenen, maar organiseert verantwoord blijven kijken en handelen. Uw rol is daarbij niet de alwetende veiligheidsverantwoordelijke: u verbindt kennis en praktijk en herkent wanneer ondersteuning nodig is.', practice: 'Werkstroom wil het dossier sluiten. Voor onderhoud van de nieuwe installatie is nog geen eigenaar, en nieuwe uitzendkrachten krijgen de instructie alleen als iemand eraan denkt.', application: 'Beleg beheer en inwerken, maak de controle vindbaar en plan een passend evaluatiemoment. Benoem de resterende risico’s en besluiten. De volledige cyclus eindigt met een actueel proces, niet alleen met een certificaat of oplevermail.' },
    ],
    exercises: ['Werkstroom verandert routes en diensten tegelijk. Welke eerste stap past?', 'Een integraal actieoverzicht stopt bij het ontvangen adviesrapport. Welke stappen horen er nog bij?', 'Medewerkers kiezen training terwijl een bronmaatregel nog niet is onderzocht. Welke aanpak past?', 'Een oplossing werkt niet voor tijdelijke medewerkers. Wat zegt dat over de evaluatie?', 'Er is een plan zonder bevoegde budgetbeslisser. Welke organisatorische schakel ontbreekt?', 'Bij piekdrukte ontstaat opnieuw een onveilige route. Welke bevinding vraagt bijstelling?', 'In het voortgangsoverleg staan documenten los van dagelijkse signalen. Welke twee informatiegroepen moeten samenkomen?', 'Een nieuwe technische stap valt buiten uw kennis. Hoe organiseert u toch voortgang?', 'Het project is afgerond, maar onderhoud is niet belegd. Wat geeft het beste beeld van duurzame verbetering?'],
    summary: ['Inventariseer in samenhang en maak ontbrekende informatie zichtbaar.', 'Organiseer deskundigheid en werkgeversbesluiten binnen duidelijke rollen.', 'Voer maatregelen uit voor alle relevante omstandigheden en groepen.', 'Controleer effect, regel borging en actualiseer de verbetercyclus.'],
  },
]
